R["cppi-m11-count-islands"] = "#include <string>\n#include <vector>\n\nvoid sink(std::vector<std::string>& g, int r, int c) {\n    if (r < 0 || r >= static_cast<int>(g.size())) return;\n    if (c < 0 || c >= static_cast<int>(g[r].size())) return;\n    if (g[r][c] != '1') return;\n    g[r][c] = '0';\n    sink(g, r + 1, c);\n    sink(g, r - 1, c);\n    sink(g, r, c + 1);\n    sink(g, r, c - 1);\n}\n\nint count_islands(std::vector<std::string> grid) {\n    int count = 0;\n    for (int r = 0; r < static_cast<int>(grid.size()); ++r) {\n        for (int c = 0; c < static_cast<int>(grid[r].size()); ++c) {\n            if (grid[r][c] == '1') {\n                ++count;\n                sink(grid, r, c);\n            }\n        }\n    }\n    return count;\n}\n";
W["cppi-m11-count-islands"] = "#include <string>\n#include <vector>\n\nvoid sink(std::vector<std::string>& g, int r, int c) {\n    if (r < 0 || r >= static_cast<int>(g.size())) return;\n    if (c < 0 || c >= static_cast<int>(g[r].size())) return;\n    if (g[r][c] != '1') return;\n    g[r][c] = '0';\n    sink(g, r + 1, c);\n    sink(g, r - 1, c);\n    sink(g, r, c + 1);\n    sink(g, r, c - 1);\n    // BUG: diagonal cells also connect \u2014 merges separate islands\n    sink(g, r + 1, c + 1);\n    sink(g, r - 1, c - 1);\n    sink(g, r + 1, c - 1);\n    sink(g, r - 1, c + 1);\n}\n\nint count_islands(std::vector<std::string> grid) {\n    int count = 0;\n    for (int r = 0; r < static_cast<int>(grid.size()); ++r) {\n        for (int c = 0; c < static_cast<int>(grid[r].size()); ++c) {\n            if (grid[r][c] == '1') {\n                ++count;\n                sink(grid, r, c);\n            }\n        }\n    }\n    return count;\n}\n";
R["cppi-checkpoint-dsa"] = "struct TreeNode {\n    int value;\n    TreeNode* left;\n    TreeNode* right;\n};\n\nbool bst_contains(const TreeNode* n, int v) {\n    if (!n) return false;\n    if (v == n->value) return true;\n    return v < n->value ? bst_contains(n->left, v)\n                        : bst_contains(n->right, v);\n}\n\nTreeNode* bst_insert(TreeNode* n, int v) {\n    if (!n) return new TreeNode{v, nullptr, nullptr};\n    if (v < n->value) n->left = bst_insert(n->left, v);\n    else if (v > n->value) n->right = bst_insert(n->right, v);\n    return n;   // duplicates ignored\n}\n";
W["cppi-checkpoint-dsa"] = "struct TreeNode {\n    int value;\n    TreeNode* left;\n    TreeNode* right;\n};\n\nbool bst_contains(const TreeNode* n, int v) {\n    if (!n) return false;\n    if (v == n->value) return true;\n    // BUG: branches inverted \u2014 smaller values searched on the right\n    return v < n->value ? bst_contains(n->right, v)\n                        : bst_contains(n->left, v);\n}\n\nTreeNode* bst_insert(TreeNode* n, int v) {\n    if (!n) return new TreeNode{v, nullptr, nullptr};\n    if (v < n->value) n->left = bst_insert(n->left, v);\n    else if (v > n->value) n->right = bst_insert(n->right, v);\n    return n;\n}\n";
R["cppi-m12-borrow-state"] = "#include <string>\n#include <vector>\n\nenum class BookState { Available, Borrowed };\n\nclass BorrowTracker {\npublic:\n    bool borrow(const std::string& isbn) {\n        auto& slot = state(isbn);\n        if (slot == BookState::Borrowed) return false;\n        slot = BookState::Borrowed;\n        return true;\n    }\n\n    bool give_back(const std::string& isbn) {\n        auto& slot = state(isbn);\n        if (slot == BookState::Available) return false;\n        slot = BookState::Available;\n        return true;\n    }\n\n    bool is_borrowed(const std::string& isbn) const {\n        for (const auto& [id, st] : states_)\n            if (id == isbn) return st == BookState::Borrowed;\n        return false;   // unknown book: not borrowed\n    }\n\nprivate:\n    std::vector<std::pair<std::string, BookState>> states_;\n\n    BookState& state(const std::string& isbn) {\n        for (auto& [id, st] : states_)\n            if (id == isbn) return st;\n        states_.emplace_back(isbn, BookState::Available);\n        return states_.back().second;\n    }\n};\n";
W["cppi-m12-borrow-state"] = "#include <string>\n#include <vector>\n\nenum class BookState { Available, Borrowed };\n\nclass BorrowTracker {\npublic:\n    bool borrow(const std::string& isbn) {\n        auto& slot = state(isbn);\n        // BUG: does not check current state \u2014 double-borrow succeeds\n        slot = BookState::Borrowed;\n        return true;\n    }\n\n    bool give_back(const std::string& isbn) {\n        auto& slot = state(isbn);\n        if (slot == BookState::Available) return false;\n        slot = BookState::Available;\n        return true;\n    }\n\n    bool is_borrowed(const std::string& isbn) const {\n        for (const auto& [id, st] : states_)\n            if (id == isbn) return st == BookState::Borrowed;\n        return false;\n    }\n\nprivate:\n    std::vector<std::pair<std::string, BookState>> states_;\n\n    BookState& state(const std::string& isbn) {\n        for (auto& [id, st] : states_)\n            if (id == isbn) return st;\n        states_.emplace_back(isbn, BookState::Available);\n        return states_.back().second;\n    }\n};\n";
